For reference, here's a Perl script I scribbled up before attempting this issue/PR, which should help show my motivations, and/or be useful to you, especially if it doesn't go anywhere.

```perl
#!/usr/bin/env perl

# Run `cargo llvm-cov` and print just the unignored uncovered lines
#
# - Ignore lines ending with `//cargo-llvm-cov:ignore`
# - Exit code is 1 if there are any unignored uncovered lines

# Run `cargo llvm-cov`
system "cargo llvm-cov --no-report >/dev/null 2>&1";

# Get "uncovered" lines
$uncovered_lines = join(
    " ",
    (
        "cargo llvm-cov report --show-missing-lines",
        "|sed -n '/^Uncovered Lines:/,\$p'",
        "|sed -n '2,\$p'",
        "|sed \"s/\$(pwd |sed 's/\\//\\\\\\//g')\\///\"",
    ),
);
for (`$uncovered_lines`) {
    ($file, $line_numbers) = split /: /;
    for (split /, /, $line_numbers) {
        if (/-/) {
            ($a, $b) = split /-/;
            for ($a..$b) {
                $uncovered{$file}{$_}++;
            }
        } else {
            $uncovered{$file}{int $_}++;
        }
    }
}

# Remove ignored lines
for (`grep -rn '//cargo-llvm-cov:ignore$' src |grep -v ':0\$' |sort`) {
    ($file, $line_number) = /^(.*):(\d+):.*$/;
    delete $uncovered{$file}{int $line_number};
}

# Remove files with no uncovered lines
for $file (sort keys %uncovered) {
    @line_numbers = sort keys %{$uncovered{$file}};
    if (scalar @line_numbers < 1) {
        delete $uncovered{$file};
    }
}

# Print report
$exit_code = 0;
# system "cargo llvm-cov report";
# print "\n";
sub condense {
    # Print array with individual numbers as a list of ranges
    my @numbers = sort { $a <=> $b } @_;
    my @ranges;
    my ($start, $prev) = ($numbers[0], $numbers[0]);
    for my $n (@numbers[1 .. $#numbers]) {
        if ($n == $prev + 1) {
            $prev = $n;
        } else {
            push @ranges, $start == $prev ? "$start" : "$start-$prev";
            ($start, $prev) = ($n, $n);
        }
    }
    push @ranges, $start == $prev ? "$start" : "$start-$prev";
    print scalar @ranges;
    print " ranges:\n\n";
    $n = 1;
    for (@ranges) {
        print "  $n. $_\n";
        $n++;
    }
}
print "# Code Coverage\n";
$n = scalar %uncovered;
if ($n == 0) {
    print "\nThere are zero files with uncovered lines.\n\n";
} else {
    if ($n == 1) {
        print "\nThere is 1 file with uncovered line(s):\n";
    } else {
        print "\nThere are $n files with uncovered lines:\n";
    }
    for $file (sort keys %uncovered) {
        @line_numbers = sort keys %{$uncovered{$file}};
        $total = scalar @line_numbers;
        if ($total > 0) {
            print "\n- `$file`: $total total lines, ";
            condense(@line_numbers);
            $exit_code = 1;
        }
    }
}

exit $exit_code;
```
